//! Which converted file serves which cores, per kernel. Generated by
//! `tools/blas_asm/gen.zig`; re-derive it rather than editing it.

const std = @import("std");

pub const Entry = struct {
    role: []const u8,
    /// Empty when the file is the same however the source is built.
    variant: []const u8,
    cores: []const []const u8,
    module: type,
};

pub const entries = [_]Entry{
    .{ .role = "isamax", .variant = "", .cores = &.{
        "la264",
    }, .module = @import("isamax_lsx.zig") },
    .{ .role = "idamax", .variant = "", .cores = &.{
        "la264",
    }, .module = @import("idamax_lsx.zig") },
    .{ .role = "icamax", .variant = "", .cores = &.{
        "la264",
    }, .module = @import("icamax_lsx.zig") },
    .{ .role = "izamax", .variant = "", .cores = &.{
        "la264",
    }, .module = @import("izamax_lsx.zig") },
    .{ .role = "isamax", .variant = "", .cores = &.{
        "la464",
    }, .module = @import("isamax_lasx.zig") },
    .{ .role = "idamax", .variant = "", .cores = &.{
        "la464",
    }, .module = @import("idamax_lasx.zig") },
    .{ .role = "icamax", .variant = "", .cores = &.{
        "la464",
    }, .module = @import("icamax_lasx.zig") },
    .{ .role = "izamax", .variant = "", .cores = &.{
        "la464",
    }, .module = @import("izamax_lasx.zig") },
    .{ .role = "isamax", .variant = "", .cores = &.{
        "la64_generic",
    }, .module = @import("isamax.zig") },
    .{ .role = "idamax", .variant = "", .cores = &.{
        "la64_generic",
    }, .module = @import("idamax.zig") },
    .{ .role = "icamax", .variant = "", .cores = &.{
        "la64_generic",
    }, .module = @import("icamax.zig") },
    .{ .role = "izamax", .variant = "", .cores = &.{
        "la64_generic",
    }, .module = @import("izamax.zig") },
};

/// The file whose function `role` is, for `core` built as `variant`, if it
/// is assembly there.
pub fn source(comptime role: []const u8, comptime core: []const u8, comptime variant: []const u8) ?type {
    @setEvalBranchQuota(1_000_000);
    inline for (entries) |e| {
        if (comptime std.mem.eql(u8, e.role, role) and (e.variant.len == 0 or std.mem.eql(u8, e.variant, variant))) {
            inline for (e.cores) |c| {
                if (comptime std.mem.eql(u8, c, core)) return e.module;
            }
        }
    }
    return null;
}
